class PriceTicker {
  private val listeners = scala.collection.mutable.ArrayBuffer.empty[Double => Unit]
  private var current = 0.0
  def subscribe(l: Double => Unit): Unit = listeners += l
  def unsubscribe(l: Double => Unit): Unit = listeners -= l

  def price_=(next: Double): Unit =
    if (next != current) {
      current = next
      listeners.toList.foreach(_(next))   // snapshot before notifying
    }
}
